-- Before: row-by-row cursor, each UPDATE its own mini-operation
DECLARE @CustomerID INT;
DECLARE loyalty_cursor CURSOR FOR
    SELECT CustomerID FROM dbo.DailyPurchases WHERE PurchaseDate = @Today;
OPEN loyalty_cursor;
FETCH NEXT FROM loyalty_cursor INTO @CustomerID;
WHILE @@FETCH_STATUS = 0
BEGIN
    UPDATE dbo.Customer SET LoyaltyPoints = LoyaltyPoints + 10 WHERE CustomerID = @CustomerID;
    FETCH NEXT FROM loyalty_cursor INTO @CustomerID;
END
CLOSE loyalty_cursor; DEALLOCATE loyalty_cursor;

-- After: one set-based statement, processed as a single batch
UPDATE c
SET c.LoyaltyPoints = c.LoyaltyPoints + 10
FROM dbo.Customer c
JOIN dbo.DailyPurchases dp ON dp.CustomerID = c.CustomerID
WHERE dp.PurchaseDate = @Today;

{
  "Comment": "Run Glue ETL job, validate output with Lambda, notify on failure",
  "StartAt": "RunGlueETLJob",
  "States": {
    "RunGlueETLJob": {
      "Type": "Task",
      "Resource": "arn:aws:states:::glue:startJobRun.sync",
      "Parameters": {
        "JobName": "daily-order-etl"
      },
      "Retry": [
        {
          "ErrorEquals": ["Glue.ConcurrentRunsExceededException", "States.Timeout"],
          "IntervalSeconds": 30,
          "MaxAttempts": 3,
          "BackoffRate": 2.0
        }
      ],
      "Catch": [
        {
          "ErrorEquals": ["States.ALL"],
          "ResultPath": "$.errorInfo",
          "Next": "NotifyFailure"
        }
      ],
      "Next": "ValidateOutput"
    },
    "ValidateOutput": {
      "Type": "Task",
      "Resource": "arn:aws:states:::lambda:invoke",
      "Parameters": {
        "FunctionName": "validate-order-etl-output",
        "Payload": {
          "jobRunId.$": "$.JobRunId"
        }
      },
      "Retry": [
        {
          "ErrorEquals": ["Lambda.ServiceException", "Lambda.TooManyRequestsException"],
          "IntervalSeconds": 10,
          "MaxAttempts": 3,
          "BackoffRate": 2.0
        }
      ],
      "Catch": [
        {
          "ErrorEquals": ["States.ALL"],
          "ResultPath": "$.errorInfo",
          "Next": "NotifyFailure"
        }
      ],
      "Next": "PipelineSucceeded"
    },
    "PipelineSucceeded": {
      "Type": "Succeed"
    },
    "NotifyFailure": {
      "Type": "Task",
      "Resource": "arn:aws:states:::sns:publish",
      "Parameters": {
        "TopicArn": "arn:aws:sns:us-east-1:111122223333:etl-pipeline-alerts",
        "Message.$": "$.errorInfo",
        "Subject": "Order ETL pipeline failed"
      },
      "Next": "PipelineFailed"
    },
    "PipelineFailed": {
      "Type": "Fail",
      "Error": "ETLPipelineFailed",
      "Cause": "See SNS notification for error details"
    }
  }
}

